check("Case 1 · less than on {1, 2, 3}", A, {(a, b) for a in A for b in A if a < b})
B = {1, 2, 3, 4, 5, 6}
check("Case 2 · divides on {1, ..., 6}", B, {(a, b) for a in B for b in B if b % a == 0})
