P = {"Ana", "Ben", "Cal"}
check("Case 5 · the trap: is a friend of", P, {("Ana", "Ben"), ("Ben", "Ana"), ("Ben", "Cal"), ("Cal", "Ben")})

def test(name, A, B, R):
    print(name)
    ok = True
    for a in sorted(A):
        outs = sorted(b for x, b in R if x == a)
        if len(outs) == 1:
            print(f"  {a} -> {outs}, exactly one output")
        elif len(outs) == 0:
            print(f"  {a} -> {outs}, no output")
            ok = False
        else:
            print(f"  {a} -> {outs}, {len(outs)} outputs")
            ok = False
    if ok:
        f = {a: b for a, b in sorted(R)}
        print(f"  a function: f = {f}")
        print(f"  range: {sorted(set(f.values()))}, the whole codomain: {set(f.values()) == B}")
    else:
        print("  not a function")


test("Case 1 · a table: the grade book", {"Ana", "Ben", "Cal"}, set(range(101)), {("Ana", 90), ("Ben", 85), ("Cal", 90)})
test("Case 2 · a rule: x * x on {-2, ..., 2} into {0, ..., 4}", set(range(-2, 3)), set(range(5)), {(x, x * x) for x in range(-2, 3)})
