def invert(name, a, b, n, codes):
    print(name)
    e = {x: (a * x + b) % n for x in range(n)}
    if n <= 10:
        print(f"  e = {e}")
    outs = set(e.values())
    one_to_one = len(outs) == len(e)
    onto = outs == set(range(n))
    if one_to_one and onto:
        print(f"  one-to-one: {one_to_one}, onto: {onto}, so e has an inverse")
        d = {y: x for x, y in e.items()}
        if n <= 10:
            print(f"  d = {d}")
        for y in codes:
            print(f"  d({y}) = {d[y]}, check e({d[y]}) = {e[d[y]]}")
    else:
        flipped = {y: x for x, y in e.items()}
        print(f"  one-to-one: {one_to_one}, onto: {onto}, so e has no inverse")
        print(f"  flipping anyway keeps {len(flipped)} of {len(e)} pairs: {flipped}")


invert("Case 1 · a bijection: e(x) = (3x + 5) mod 7", 3, 5, 7, [1, 4, 2])
invert("Case 2 · a shift: e(x) = (x + 3) mod 7", 1, 3, 7, [0, 3])
invert("Case 3 · the trap, no inverse: e(x) = (2x + 1) mod 6", 2, 1, 6, [3])
invert("Case 4 · a word problem: e(x) = (3x + 5) mod 26", 3, 5, 26, [11, 5, 17])
inv3 = pow(3, -1, 26)
e = {x: (3 * x + 5) % 26 for x in range(26)}
d = {y: x for x, y in e.items()}
print(f"Example 9's formula: 3 * {inv3} = {3 * inv3} = 26 + 1, so d(y) = {inv3}(y - 5) mod 26")
print("  it agrees with the flipped dict at all 26 codes:", all(d[y] == inv3 * (y - 5) % 26 for y in range(26)))

